///   let mut y = x.borrow_mut();
///   *y += 1;
///   baz().await;
/// }
///
/// async fn bar(x: &RefCell<u32>) {
///   let mut y = x.borrow_mut();
///   *y += 1;
///   drop(y); // explicit drop
///   baz().await;
/// }
